SELECT o.*, d.name AS device_name, d.device_no, ur.real_name AS reporter_name, uh.real_name AS handler_name FROM repair_order o LEFT JOIN device d ON o.device_id = d.id LEFT JOIN user ur ON o.reporter_id = ur.id LEFT JOIN user uh ON o.handler_id = uh.id
AND o.status = #{status} AND o.device_id = #{deviceId}
AND (o.order_no LIKE CONCAT('%', #{keyword}, '%') OR d.name LIKE CONCAT('%', #{keyword}, '%') OR o.title LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY o.id DESC LIMIT #{offset}, #{size}

